import React, { HTMLAttributes } from 'react';

import { getDomain } from '@helpers/domain.helper';

interface IPohodnikChevronProps extends HTMLAttributes<HTMLCanvasElement> {
  header: string;
  subheader: string;
  url: string;
}
const PohodnikChevron = ({ header, subheader, url, ...rest }: IPohodnikChevronProps) => {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);

  React.useEffect(() => {
    if (!canvasRef.current) {
      return;
    }

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    if (!ctx) return;

    function drawStar(
      cx: number,
      cy: number,
      spikes: number,
      outerRadius: number,
      innerRadius: number,
    ) {
      if (!ctx) return;
      let rot = (Math.PI / 2) * 3;
      let x = cx;
      let y = cy;
      const step = Math.PI / spikes;

      ctx.beginPath();
      ctx.moveTo(cx, cy - outerRadius);
      for (let i = 0; i < spikes; i += 1) {
        x = cx + Math.cos(rot) * outerRadius;
        y = cy + Math.sin(rot) * outerRadius;
        ctx.lineTo(x, y);
        rot += step;

        x = cx + Math.cos(rot) * innerRadius;
        y = cy + Math.sin(rot) * innerRadius;
        ctx.lineTo(x, y);
        rot += step;
      }
      ctx.shadowColor = '#adadad';
      ctx.shadowBlur = 6;
      ctx.lineTo(cx, cy - outerRadius);
      ctx.closePath();
      // ctx.lineWidth=1;
      // ctx.strokeStyle='#fe4542';
      // ctx.stroke();
      ctx.fillStyle = '#feffed';
      ctx.fill();

      ctx.shadowColor = 'transparent';
      ctx.shadowBlur = 0;
    }

    drawStar(256, 256, 24, 220, 206);

    const thumbImg = document.createElement('img');

    thumbImg.src = url;
    thumbImg.onload = function () {
      ctx.save();
      ctx.beginPath();
      ctx.arc(256, 256, 160, 0, Math.PI * 2, true);
      ctx.closePath();
      ctx.clip();

      ctx.drawImage(thumbImg, 96, 96, 320, 320);

      ctx.beginPath();
      ctx.arc(255, 255, 0, 0, Math.PI * 2, true);
      ctx.clip();
      ctx.closePath();
      ctx.restore();
    };

    function textCircle(
      text: string,
      x: number,
      y: number,
      radius: number,
      space = 0,
      top = false,
    ) {
      if (!ctx) return;
      const numRadsPerLetter = (Math.PI - space * 2) / text.length;
      ctx.save();
      ctx.translate(x, y);
      const k = top ? 1 : -1;
      ctx.rotate(-k * ((Math.PI - numRadsPerLetter) / 2 - space));
      for (let i = 0; i < text.length; i += 1) {
        ctx.save();
        ctx.rotate(k * i * numRadsPerLetter);
        ctx.textAlign = 'center';
        ctx.textBaseline = !top ? 'top' : 'bottom';
        ctx.fillText(text[i], 0, -k * radius);
        ctx.restore();
      }
      ctx.restore();
    }
    ctx.beginPath();
    const r = 169;
    ctx.arc(150, 150, r, 0, Math.PI * 2, false);
    ctx.closePath();
    ctx.fillStyle = '#535353';
    ctx.font = "bold 22px 'Russo One'";

    textCircle(header, 256, 256, r, Math.PI / 122, true);

    ctx.font = "22px 'Russo One'";
    textCircle(subheader, 256, 256, 175, Math.PI / 4, false);

    const thumbImg1 = document.createElement('img');

    thumbImg1.src = `https://${getDomain()}/icon_96x96.11d65c0570e7f068e7f3501c3ba2ed74.png`;
    thumbImg1.onload = function () {
      ctx.save();
      ctx.drawImage(thumbImg1, 48, 255, 42, 42);
      ctx.translate(canvas.width / 2, canvas.height / 2);
      ctx.scale(-1, 1);
      ctx.drawImage(thumbImg1, -162, 0, -42, 42);
      ctx.restore();
    };
  }, [canvasRef, header, subheader, url]);

  return <canvas ref={canvasRef} width="512" height="512" {...rest} />;
};

export default PohodnikChevron;
